CREATE DEFINER=`alumno27.andreoli.castro.thiago`@`localhost` FUNCTION `produOrder`(fechaInicio DATE, fechaFin DATE, codeprodu TEXT) RETURNS float
    DETERMINISTIC
BEGIN
	DECLARE mayorVenta FLOAT DEFAULT 0;
    
    SELECT MAX(ord.priceEach) INTO mayorVenta FROM orderdetails ord
    JOIN orders o ON o.orderNumber = ord.orderNumber
    WHERE (codeprodu = ord.productCode) AND (o.orderDate BETWEEN fechaInicio AND fechaFin); 
    
    if(mayorVenta is null) then 
    set mayorVenta = 0;
    end if;
    
    RETURN mayorVenta;
    
END ;;
DELIMITER ;
