CREATE DEFINER=`alumno27.andreoli.castro.thiago`@`localhost` PROCEDURE `borrarOrden`(in orden int, out cant int)
BEGIN
	
    SET cant = (SELECT count(*) FROM orderdetails
    WHERE orden = orderNumber);
    
    if(cant is null) then
    SET cant = 0;
    
    else
    DELETE FROM orderdetails
    WHERE orden = orderNumber;
    
    DELETE FROM orders
    WHERE orden = orderNumber;
	
    end if;	
   

END ;;
DELIMITER ;
