CREATE DEFINER=`alumno27.andreoli.castro.thiago`@`localhost` PROCEDURE `modificarComment`(in orden int, in comm TEXT, out funciono int)
BEGIN
	IF EXISTS(SELECT orderNumber FROM orders WHERE orderNumber = orden)THEN
    
    UPDATE orders
    SET comments = comm
    WHERE orderNumber = orden;
    
    SET funciono = 1;
    
    ELSE
    
    SET funciono = 0;
    
    END IF;

END ;;
DELIMITER ;
