CREATE DEFINER=`alumno27.andreoli.castro.thiago`@`localhost` PROCEDURE `sp_insert_customers_orders`()
BEGIN
    DECLARE i INT DEFAULT 1;
    DECLARE v_customerNumber INT;
    DECLARE v_orderNumber INT;
    DECLARE v_numOrders INT;
    DECLARE j INT;
    DECLARE v_orderDate DATE;
    DECLARE v_requiredDate DATE;
    DECLARE v_shippedDate DATE;
    DECLARE v_status VARCHAR(15);
    DECLARE v_comments TEXT;

    -- Arrays simulados con datos realistas
    -- Nombres de empresas (se construyen combinando partes)
    -- Ciudades, estados, países
    -- Representantes de ventas existentes en la tabla employees

    SET v_customerNumber = (SELECT IFNULL(MAX(customerNumber), 200) + 1 FROM classicmodels.customers);
    SET v_orderNumber    = (SELECT IFNULL(MAX(orderNumber), 11000) + 1 FROM classicmodels.orders);

    WHILE i <= 10000 DO

        -- ---- Datos del cliente ----------------------------------------
        INSERT INTO classicmodels.customers (
            customerNumber,
            customerName,
            contactLastName,
            contactFirstName,
            phone,
            addressLine1,
            addressLine2,
            city,
            state,
            postalCode,
            country,
            salesRepEmployeeNumber,
            creditLimit
        )
        VALUES (
            v_customerNumber,

            -- customerName: combinación de adjetivo + sustantivo + tipo empresa
            CONCAT(
                ELT(1 + MOD(i,  20), 'Alpha','Beta','Gamma','Delta','Sigma','Omega','Nova','Prime',
                    'Elite','Global','Pacific','Atlantic','Summit','Pioneer','Apex','Vertex',
                    'Horizon','Zenith','Stellar','Eagle'),
                ' ',
                ELT(1 + MOD(i*3, 25), 'Trading','Gifts','Models','Collectibles','Imports',
                    'Exports','Distributors','Solutions','Ventures','Industries',
                    'Group','Partners','Associates','Holdings','Enterprises',
                    'Supplies','Wholesale','Retail','Direct','International',
                    'Commerce','Services','Logistics','Depot','Market'),
                ' ',
                ELT(1 + MOD(i*7, 6), 'Ltd.','Inc.','Co.','Corp.','S.A.','GmbH')
            ),

            -- contactLastName
            ELT(1 + MOD(i*11, 40),
                'Smith','Johnson','Williams','Brown','Jones','Garcia','Miller','Davis',
                'Rodriguez','Martinez','Hernandez','Lopez','Gonzalez','Wilson','Anderson',
                'Thomas','Taylor','Moore','Jackson','Martin','Lee','Perez','Thompson','White',
                'Harris','Sanchez','Clark','Ramirez','Lewis','Robinson','Walker','Young',
                'Allen','King','Wright','Scott','Torres','Nguyen','Hill','Flores'),

            -- contactFirstName
            ELT(1 + MOD(i*13, 30),
                'James','Mary','John','Patricia','Robert','Jennifer','Michael','Linda',
                'William','Barbara','David','Susan','Richard','Jessica','Joseph','Sarah',
                'Thomas','Karen','Charles','Lisa','Christopher','Nancy','Daniel','Betty',
                'Matthew','Margaret','Anthony','Sandra','Mark','Ashley'),

            -- phone
            CONCAT(
                '+', 1 + MOD(i, 99),
                ' ', 100 + MOD(i*17, 900),
                ' ', 1000000 + MOD(i*31, 9000000)
            ),

            -- addressLine1
            CONCAT(
                100 + MOD(i*19, 9900), ' ',
                ELT(1 + MOD(i*23, 10),'Main St','Oak Ave','Maple Rd','Pine Blvd',
                    'Cedar Ln','Elm St','Park Ave','Lake Dr','River Rd','Hill St')
            ),

            -- addressLine2
            CASE WHEN MOD(i, 3) = 0
                 THEN CONCAT('Suite ', 100 + MOD(i, 900))
                 ELSE NULL
            END,

            -- city
            ELT(1 + MOD(i*29, 50),
                'New York','Los Angeles','Chicago','Houston','Phoenix','Philadelphia',
                'San Antonio','San Diego','Dallas','San Jose','Austin','Jacksonville',
                'Fort Worth','Columbus','Charlotte','Indianapolis','San Francisco','Seattle',
                'Denver','Nashville','Oklahoma City','El Paso','Washington','Boston','Memphis',
                'Louisville','Portland','Las Vegas','Milwaukee','Albuquerque',
                'London','Paris','Madrid','Berlin','Rome','Amsterdam','Brussels','Vienna',
                'Sydney','Melbourne','Toronto','Vancouver','Tokyo','Singapore','Dubai',
                'Mexico City','Buenos Aires','São Paulo','Mumbai','Shanghai'),

            -- state
            ELT(1 + MOD(i*37, 20),
                'CA','TX','NY','FL','IL','PA','OH','GA','NC','MI',
                'NSW','VIC','ON','BC','NULL','NULL','NULL','NULL','NULL','NULL'),

            -- postalCode
            LPAD(10000 + MOD(i*41, 89999), 5, '0'),

            -- country
            ELT(1 + MOD(i*43, 20),
                'USA','USA','USA','USA','USA','USA','UK','France','Germany','Spain',
                'Italy','Australia','Canada','Japan','Singapore','Netherlands',
                'Argentina','Brazil','India','China'),

            -- salesRepEmployeeNumber (empleados existentes en classicmodels)
            ELT(1 + MOD(i*47, 7), 1166, 1165, 1188, 1216, 1286, 1323, 1337),

            -- creditLimit
            ROUND((5000 + MOD(i*53, 195000)) / 1000.0) * 1000
        );

        -- ---- Órdenes para este cliente --------------------------------
        -- Cada cliente tendrá entre 1 y 5 órdenes
        SET v_numOrders = 1 + MOD(i * 59, 5);
        SET j = 1;

        WHILE j <= v_numOrders DO

            SET v_orderDate = DATE_ADD('2020-01-01', INTERVAL MOD(i*j*67, 1826) DAY);
            SET v_requiredDate = DATE_ADD(v_orderDate, INTERVAL 7 + MOD(i*j, 21) DAY);

            -- status y shippedDate
            SET v_status = ELT(1 + MOD(i*j*71, 5),
                               'Shipped','Shipped','Shipped','In Process','Cancelled');

            IF v_status = 'Shipped' THEN
                SET v_shippedDate = DATE_ADD(v_orderDate, INTERVAL 1 + MOD(i*j, 6) DAY);
            ELSEIF v_status = 'In Process' THEN
                SET v_shippedDate = NULL;
            ELSE
                SET v_shippedDate = NULL;
            END IF;

            -- comments opcionales
            SET v_comments = CASE MOD(i*j, 5)
                WHEN 0 THEN 'Priority order. Handle with care.'
                WHEN 1 THEN NULL
                WHEN 2 THEN NULL
                WHEN 3 THEN CONCAT('Customer reference: REF-', i, '-', j)
                ELSE    NULL
            END;

            INSERT INTO classicmodels.orders (
                orderNumber,
                orderDate,
                requiredDate,
                shippedDate,
                status,
                comments,
                customerNumber
            )
            VALUES (
                v_orderNumber,
                v_orderDate,
                v_requiredDate,
                v_shippedDate,
                v_status,
                v_comments,
                v_customerNumber
            );

            SET v_orderNumber = v_orderNumber + 1;
            SET j = j + 1;
        END WHILE;

        SET v_customerNumber = v_customerNumber + 1;
        SET i = i + 1;
    END WHILE;

    SELECT CONCAT('Proceso completado. Clientes insertados: 10000. ',
                  'Órdenes insertadas: ', v_orderNumber -
                  (SELECT IFNULL(MAX(orderNumber), 11000) + 1 FROM classicmodels.orders)) AS resultado;
END ;;
DELIMITER ;
